/* Colored portrait particles derived from the image supplied by the site owner.
   Subject pixels and colors are preserved; the surrounding speckled background is excluded. */
((root)=>{
  "use strict";
  const binary=atob("");
  const points=new Float32Array(binary.length/11*7);
  for(let i=0;i<binary.length/11;i++){
    const p=i*11,o=i*7;
    for(let j=0;j<4;j++) points[o+j]=(binary.charCodeAt(p+j*2)+binary.charCodeAt(p+j*2+1)*256)/(j<2?100:1000);
    for(let j=0;j<3;j++) points[o+4+j]=binary.charCodeAt(p+8+j)/255;
  }
  const portrait={cols:90,rows:148,cell:[0.90840841,0.67567568],stride:7,yaw:.18,points};
  root.BlueFlutePortrait=portrait;
  if(typeof module!=="undefined") module.exports=portrait;
})(typeof window==="undefined"?globalThis:window);
